const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>nav.classList.remove('open')));
const quotes=[...document.querySelectorAll('.quote')],dots=[...document.querySelectorAll('.dots button')];dots.forEach((dot,i)=>dot.addEventListener('click',()=>{quotes.forEach((q,j)=>q.classList.toggle('active',i===j));dots.forEach((d,j)=>d.classList.toggle('active',i===j))}));
document.querySelector('#booking-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const msg=`Hello Zeelie Taxis, I would like to request a booking.\n\nName: ${f.get('name')}\nContact: ${f.get('contact')}\nPickup: ${f.get('pickup')}\nDestination: ${f.get('destination')}\nDate: ${f.get('date')}\nPassengers: ${f.get('passengers')}\nNotes: ${f.get('message')||'None'}`;window.open(`https://wa.me/27825557441?text=${encodeURIComponent(msg)}`,'_blank','noopener')});
document.querySelector('#year').textContent=new Date().getFullYear();
const gallery=document.querySelector('.gallery-track'),gallerySlides=[...gallery.querySelectorAll('figure')],galleryCurrent=document.querySelector('#gallery-current');
const galleryStep=()=>gallerySlides[0].getBoundingClientRect().width+16;
let galleryPaused=false,galleryAuto;
const moveGallery=direction=>{const current=Math.round(gallery.scrollLeft/galleryStep()),next=direction>0?(current+1)%gallerySlides.length:(current-1+gallerySlides.length)%gallerySlides.length;gallery.scrollTo({left:next*galleryStep(),behavior:'smooth'})};
const restartGallery=()=>{clearInterval(galleryAuto);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)galleryAuto=setInterval(()=>{if(!galleryPaused&&!document.hidden)moveGallery(1)},6000)};
document.querySelector('[data-gallery-prev]').addEventListener('click',()=>{moveGallery(-1);restartGallery()});
document.querySelector('[data-gallery-next]').addEventListener('click',()=>{moveGallery(1);restartGallery()});
gallery.addEventListener('scroll',()=>{const active=Math.max(0,Math.min(gallerySlides.length-1,Math.round(gallery.scrollLeft/galleryStep())));galleryCurrent.textContent=String(active+1).padStart(2,'0')},{passive:true});
gallery.addEventListener('mouseenter',()=>galleryPaused=true);gallery.addEventListener('mouseleave',()=>galleryPaused=false);gallery.addEventListener('focusin',()=>galleryPaused=true);gallery.addEventListener('focusout',()=>galleryPaused=false);restartGallery();
document.querySelectorAll('[data-card-slides]').forEach((card,cardIndex)=>{const sources=card.dataset.cardSlides.split('|'),wrap=document.createElement('div');wrap.className='card-slides';wrap.setAttribute('aria-hidden','true');const layers=[document.createElement('i'),document.createElement('i')];layers.forEach(layer=>wrap.appendChild(layer));card.prepend(wrap);let active=0,index=0,paused=false;layers[0].style.backgroundImage=`url("${sources[0]}")`;layers[0].classList.add('active');card.addEventListener('mouseenter',()=>paused=true);card.addEventListener('mouseleave',()=>paused=false);card.addEventListener('focusin',()=>paused=true);card.addEventListener('focusout',()=>paused=false);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)setTimeout(()=>setInterval(()=>{if(paused||document.hidden)return;index=(index+1)%sources.length;const next=1-active;layers[next].style.backgroundImage=`url("${sources[index]}")`;layers[next].classList.add('active');layers[active].classList.remove('active');active=next},7000),cardIndex*850)});
